const ctx = $('When Called').first().json;
const c = $input.first().json;
const t = {
  intake_confirmed: { subject: 'Welcome to Williams Equity Capital - your case is open', body: 'Hi ' + c.first_name + ', your case is open. Your 3-day cancellation window is running; dispute work starts after it closes. You owe nothing until services are performed.' },
  letters_mailed: { subject: 'Your dispute letters are on the way', body: 'Hi ' + c.first_name + ', your dispute letters have been mailed certified to the credit bureaus. They have 30 days to respond.' },
  round_results: { subject: 'Update on your credit dispute round', body: 'Hi ' + c.first_name + ', the bureaus have responded. Log in to see which items were removed or corrected.' },
  case_closed: { subject: 'Your credit repair case is complete', body: 'Hi ' + c.first_name + ', all disputable items have been resolved. A summary is available in your portal.' }
};
const msg = t[ctx.event_type] || t.round_results;
return [{ json: { ...c, event_type: ctx.event_type, subject: msg.subject, body: msg.body } }];

const resp = $input.first().json;
const msg = $('Build Message').first().json;
const channel = resp.sid ? 'sms' : 'email';
return [{ json: { case_id: msg.case_id, event_type: msg.event_type, channel } }];
